#include "KS/SRC/entity_shared.h"
#include "KS/SRC/stringx.h"
#include "KS/SRC/inputmgr_shared.h"
#include "KS/SRC/anim_shared.h"

extern "C" int sprintf(char *, const char *, ...);

class generic_anim
{
public:
  generic_anim (const stringx& path, const stringx& name) { my_base_name = name; dummy = false; cur_state = cur_anim = 0; left_down = right_down = false; };
  virtual ~generic_anim () { };

  virtual void update (bool collide, bool jump, bool spray, float *alpha) = 0;
  virtual void spawn () = 0;
  virtual void switch_anims () = 0;

protected:
  stringx my_base_name;
  int cur_state, cur_anim;
  bool dummy;
  bool left_down, right_down;
};

class generic_anim_misc : public generic_anim
{
public:
  generic_anim_misc (entity *entity, const stringx& path, const stringx& name);
  generic_anim_misc (entity **entities, const stringx& path, const stringx& name, const char **prefixes, int count);

  void construct (entity **entities, const stringx& path, const stringx& name, const char **prefixes, int count);
  virtual ~generic_anim_misc ();

  void update (bool collide, bool jump, bool spray, float *alpha);
  void spawn () { generic_anim_state = GA_SPAWN; };
  void switch_anims ();

private:
  static const char* generic_anim_names[];
  int generic_anims[5];
  int generic_anim_state;
  int items_count;
  stringx* items_prefixes;
  entity **my_entities;

  typedef enum { GA_IDLE, GA_COLLIDE, GA_AFTER_COLLIDE, GA_JUMP, GA_SPRAY, GA_SPAWN };
};

void generic_anim_misc::switch_anims ()
{
	if (!dummy)
		return;

	input_mgr* inputmgr = input_mgr::inst();

	if (inputmgr->get_control_state(JOYSTICK_DEVICE, PSX_L1) == AXIS_MAX)
	{
		if (!left_down)
		{
			left_down = true;
			cur_anim--;

			if (cur_anim <= 0)
			{
				cur_state--;

				if (cur_state < 0)
					cur_state = GA_SPRAY;

				cur_anim = generic_anims[cur_state];
			}

			for (int j = 0; j < items_count; j++)
			{
				char anim[256];
				if (j == 0)
					sprintf (anim, "%s_%s_%d", my_base_name.c_str(), generic_anim_names[cur_state], cur_anim);
				else
					sprintf (anim, "%s_%s_%s_%d", my_base_name.c_str(), items_prefixes[j].c_str(), generic_anim_names[cur_state], cur_anim);

		    my_entities[j]->play_anim (ANIM_PRIMARY, anim, BLEND_TIME, ANIM_LOOPING | ANIM_TWEEN | ANIM_NONCOSMETIC);
			}
		}
	}
	else
	{
		left_down = false;
	}

	if (inputmgr->get_control_state(JOYSTICK_DEVICE, PSX_R1) == AXIS_MAX)
	{
		if (!right_down)
		{
			right_down = true;
			cur_anim++;

			if (cur_anim > generic_anims[cur_state])
			{
				cur_anim = 1;
				cur_state++;
				if (cur_state > GA_SPRAY)
					cur_state = 0;
			}

			for (int j = 0; j < items_count; j++)
			{
				char anim[256];
				if (j == 0)
					sprintf (anim, "%s_%s_%d", my_base_name.c_str(), generic_anim_names[cur_state], cur_anim);
				else
					sprintf (anim, "%s_%s_%s_%d", my_base_name.c_str(), items_prefixes[j].c_str(), generic_anim_names[cur_state], cur_anim);

		    my_entities[j]->play_anim (ANIM_PRIMARY, anim, BLEND_TIME, ANIM_LOOPING | ANIM_TWEEN | ANIM_NONCOSMETIC);
			}
		}
	}
	else
	{
		right_down = false;
	}
}
